/**
 * 생성 파일 — 손으로 고치지 않는다. `pnpm gen:blog`(`scripts/gen-blog.ts`)가 블로그 글(`src/site/blog/posts/<slug>/<lang>.md`)을 검사하고
 * HTML 로 렌더해 쓴다. **공개 글(`draft: false`)만** 싣는다 — 초안은 운영 번들에 들어오지 않는다(로컬 미리보기는 원문에서 바로 만든다).
 * import 는 없다(값 파일). 본문·표지는 HTML 의 base64(UTF-8) — 글의 예시 문자열이 소스 트리의 문자열 리터럴이 되지 않게(문서 값 파일과 같은 이유).
 */

export interface BlogPostRecord {
  readonly slug: string;
  readonly lang: 'en' | 'ko';
  readonly title: string;
  readonly description: string;
  readonly date: string;
  readonly updated: string | null;
  readonly author: string;
  readonly tags: readonly string[];
  readonly draft: boolean;
  /** 읽는 시간(분, 1 이상). */
  readonly minutes: number;
  /** 본문이 싣는 스크린샷 id(등장 순, 중복 없음). */
  readonly shots: readonly string[];
  /** 본문 HTML 의 base64. 스크린샷 자리는 `<!--shot:<id>:<base64url 대체 글>-->`(사이트가 이미지 표로 채운다). */
  readonly body: string;
  /** 표지 그림(`<figure>` 인라인 SVG)의 base64 — 없으면 `null`. */
  readonly cover: string | null;
}

